  height: 30px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  opacity: 0 !important;
  pointer-events: auto !important;
}

.tm-header-right .tm-btn-icon { color: #9bbfaa !important; }

/* ---------- 3. 故事区 & 聊天框 ---------- */
.tm-story { padding: 0 !important; -webkit-overflow-scrolling: touch !important; }

.tm-para-char, .tm-para-user {
  width: 100% !important;
  margin: 0 !important;
  border-radius: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 20px 16px !important;
}

.tm-para-user { background: rgba(255, 255, 255, 0.03) !important; }

.tm-body-char, .tm-body-user {
  color: var(--text-main) !important;
  font-size: 14.5px !important;
  font-weight: 300 !important;
  line-height: 1.95 !important;
  letter-spacing: 0.5px !important;
  text-shadow: none !important;
}

/* ---------- 4. 对话（引用框） ---------- */
.tm-quote-block {
  border-left: 3px solid #6e9c81 !important;
  background: linear-gradient(to right, rgba(110, 156, 129, 0.15), rgba(110, 156, 129, 0.0)) !important;
  padding: 10px 14px !important;
  border-radius: 0 8px 8px 0 !important;
  margin: 14px 0 !important;
}

.tm-quote {
  color: var(--text-quote) !important;
  font-style: italic !important;
  font-weight: 400 !important;
}

/* ---------- 5. 重点文字 ---------- */
.tm-bold {
  color: var(--text-bold) !important;
  font-weight: 700 !important;
  background: rgba(209, 240, 223, 0.15) !important; 
  padding: 1px 5px !important;
  border-radius: 4px !important;
  -webkit-text-fill-color: var(--text-bold) !important;
  text-shadow: none !important;
}

.tm-action { color: #6a8c76 !important; font-style: italic !important; }

/* ---------- 6. 消息内头部信息 ---------- */
.tc-header { padding: 0 0 10px 0 !important; }
.tc-avatar-frame {
  border-radius: 50% !important;
  border: 1px solid rgba(155, 191, 170, 0.2) !important;
  box-shadow: none !important;
  overflow: hidden;
}
.tc-meta-title { color: #9bbfaa !important; font-weight: 400 !important; font-size: 14px !important; }
.tc-stat {
  background: rgba(155, 191, 170, 0.08) !important;
  color: #6a8c76 !important;
  border: 1px solid rgba(155, 191, 170, 0.15) !important;
  border-radius: 99px !important;
  font-size: 10px !important;
}
.tc-divider {
  border: none !important;
  height: 1px !important;
  background: linear-gradient(90deg, transparent, rgba(155, 191, 170, 0.1), transparent) !important;
}
.tc-divider-text::before { content: '✦' !important; color: rgba(155, 191, 170, 0.2) !important; }

/* ---------- 7. 底部输入区：同步高透墨绿玻璃 ---------- */
.tm-compose {
  /* 👇 与顶栏一致的高通透底色 */
  background: rgba(10, 38, 24, 0.35) !important; 
  /* 👇 提高模糊度，强调磨砂玻璃的厚度感 */
  backdrop-filter: blur(30px) saturate(160%) !important;
  -webkit-backdrop-filter: blur(30px) saturate(160%) !important;
  border-top: 1px solid rgba(209, 240, 223, 0.1) !important;
  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 0 rgba(255, 255, 255, 0.03) !important; 
  border-radius: 22px 22px 0 0 !important;
  padding-bottom: calc(12px + var(--nuo-safe-bottom, 0px)) !important;
}

.tm-input {
  background: rgba(255, 255, 255, 0.06) !important; 
  color: #b8dcc9 !important;
  border: 1px solid rgba(155, 191, 170, 0.2) !important;
  border-radius: 16px !important;
  font-size: 15px !important;
  font-weight: 300 !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2) !important; 
}
.tm-input:focus {
  background: rgba(255, 255, 255, 0.1) !important;
  border-color: rgba(155, 191, 170, 0.5) !important;
}
.tm-input::placeholder { color: rgba(106, 140, 118, 0.5) !important; }

.tm-send-btn {
  border-radius: 50% !important;
  width: 40px !important;
  height: 40px !important;
  color: #9bbfaa !important;
  background: rgba(155, 191, 170, 0.1) !important;
  border: 1px solid rgba(155, 191, 170, 0.25) !important;
}
.tm-send-btn.ready { background: #4a8c68 !important; color: #ffffff !important; border-color: transparent !important; }

.tm-regen-btn { color: #6a8c76 !important; }
.tm-regen-btn.active {
  background: rgba(155, 191, 170, 0.15) !important;
  color: #b8dcc9 !important;
  border-color: rgba(155, 191, 170, 0.3) !important;
}
.tm-bond-btn { color: #9ec9af !important; }

.tm-story::-webkit-scrollbar { width: 2px !important; }
.tm-story::-webkit-scrollbar-thumb { background: rgba(155, 191, 170, 0.15) !important; border-radius: 2px !important; }

.tm-para-char, .tm-para-user, .tm-send-btn, .tm-btn-icon { -webkit-tap-highlight-color: transparent !important; }

/*⁣​⁠⁠⁠⁠​​‍​‌​​‌‍​⁠‌‍​‍‌⁠‌​⁠‌‍‍⁠​‌‌‌⁠‍‌‌​​‌‍​‌​⁠‌​⁠​‌‍​⁠‌‌⁠‌⁠‌⁠‌‍‌‌⁣ ============================================================
   此时此刻 × 自由副刊·夜间 · 完整版
   ============================================================
   ▸ 三行头图用伪元素 cover，绝不变形
   ▸ 用户 (FR.EEDOM) / 楼层数 / 计时 全部对齐
   ▸ 思维链折叠装饰文案 + 展开卡片
   ▸ 底栏图标 / 输入框 / 头像 可调
   ▸ 输入栏行高 0.9，收窄
   ============================================================ */

:root {
  --tm-ink:       #dcdcd2;
  --tm-mark:      #9d9d9d;
  --tm-muted:     #888888;
  --tm-line:      #2a2a2a;
  --tm-line-soft: #1f1f1f;
  --tm-bg:        #0d0d0d;
  --tm-topbar:    rgba(26, 26, 26, 0.9);
  --tm-paper:     rgba(16, 16, 16, 0.92);
  --tm-paper-soft:rgba(26, 26, 26, 0.9);
  --tm-accent:    #dcdcd2;
  --tm-underline: #555555;

  /* ★ 三行图床：角色 */
  --tm-char-img1: url('https://imgbed.heliar.top/i/QJ6qo1JFbEw7nEXJ_1789071311664.webp');
  --tm-char-img3: url('https://imgbed.heliar.top/i/CxNnpvsr8zbdfMZw_1789502077118.webp');
  /* ★ 三行图床：用户 */
  --tm-user-img1: url('https://imgbed.heliar.top/i/inwMoRHrSJHd3P9x_1789071316031.webp');
  --tm-user-img3: url('https://imgbed.heliar.top/i/kslCpffioMmabDGY_1789502062697.webp');
  /* ★ 中横图：两边共用 */
  --tm-img2:      url('https://imgbed.heliar.top/i/VRLeXoom7x0exCkD_无标题144_20260917212255.webp');
}

/* ════════════════════════════════════════════════════════════
   1. 全局底色
   ════════════════════════════════════════════════════════════ */
#this-moment-screen {
  background: var(--tm-bg) !important;
  color: var(--tm-ink) !important;
}
.tm-bg-image { display: none !important; }
.tm-bg-overlay {
  background: rgba(13, 13, 13, 0.55) !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
::selection {
  background: var(--tm-underline) !important;
  color: var(--tm-ink) !important;
}

/* ════════════════════════════════════════════════════════════
   2. 顶栏
   ════════════════════════════════════════════════════════════ */
.tm-header {
  background: var(--tm-topbar) !important;
  border-bottom: 1px solid var(--tm-line) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
.tm-header-name {
  color: var(--tm-ink) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  letter-spacing: 0.04em !important;
}
.tm-top-vs { color: var(--tm-muted) !important; }

.tm-btn-icon {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
}
.tm-btn-icon:hover { color: #ffffff !important; }
.tm-btn-icon svg,
.tm-btn-icon svg * {
  color: var(--tm-ink) !important;
  stroke: var(--tm-ink) !important;
}
.tm-btn-icon:hover svg,
.tm-btn-icon:hover svg * {
  color: #ffffff !important;
  stroke: #ffffff !important;
}
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  background: transparent !important;
  border: 1px solid transparent !important;
  border-radius: 0 !important;
}
.tm-top-drop-btn:hover,
.tm-top-drop-btn-user:hover {
  background: var(--tm-paper-soft) !important;
  border-color: var(--tm-line) !important;
}
.tm-header-avatar {
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  filter: none !important;
  opacity: 1 !important;
}
.tm-header-avatar-fallback {
  background: var(--tm-line-soft) !important;
  border-radius: 0 !important;
}

/* ════════════════════════════════════════════════════════════
   3. 故事区
   ════════════════════════════════════════════════════════════ */
.tm-story {
  background: transparent !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  counter-reset: msg !important;
}
.tm-story::-webkit-scrollbar { width: 3px !important; }
.tm-story::-webkit-scrollbar-thumb {
  background: var(--tm-underline) !important;
  border-radius: 0 !important;
}
.tm-story::-webkit-scrollbar-track { background: transparent !important; }

.tm-load-more {
  background: transparent !important;
  color: var(--tm-muted) !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
}
.tm-load-more:hover {
  background: var(--tm-paper-soft) !important;
  color: var(--tm-ink) !important;
}

/* ════════════════════════════════════════════════════════════
   4. 消息卡片
   ════════════════════════════════════════════════════════════ */
.tm-para {
  padding: 0 !important;
  margin: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  counter-increment: msg !important;
}

.tm-para-char,
.tm-para-user {
  position: relative !important;
  width: 100% !important;
  max-width: 100% !important;
  margin: 20px 0 !important;
  padding: 428px 16px 12px 16px !important;
  background: var(--tm-paper) !important;
  border-top: 1px solid var(--tm-line) !important;
  border-bottom: 1px solid var(--tm-line) !important;
  border-left: 0 !important;
  border-right: 0 !important;
  border-radius: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  min-height: 420px !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
}
.tm-para.tm-selected {
  outline: 1px solid var(--tm-accent) !important;
  outline-offset: 2px !important;
}

/* ════════════════════════════════════════════════════════════
   5. 三行头图
   ════════════════════════════════════════════════════════════ */
.tm-para-char::before {
  content: '' !important;
  position: absolute !important;
  top: 12px !important;
  left: 0 !important;
  right: 0 !important;
  height: 242px !important;
  z-index: 5 !important;
  pointer-events: none !important;
  background-color: transparent !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position:
    20px top,
    left 130px !important;
  background-size:
    120px 120px,
    100% 100px !important;
  background-image:
    var(--tm-char-img1),
    var(--tm-img2) !important;
}
.tm-para-char::after {
  content: '' !important;
  position: absolute !important;
  top: 264px !important;
  left: 0 !important;
  right: 0 !important;
  height: 140px !important;
  z-index: 5 !important;
  pointer-events: none !important;
  background-image: var(--tm-char-img3) !important;
  background-position: center center !important;
  background-size: 100% auto !important;
  background-repeat: no-repeat !important;
}

.tm-para-user::before {
  content: '' !important;
  position: absolute !important;
  top: 12px !important;
  left: 0 !important;
  right: 0 !important;
  height: 242px !important;
  z-index: 5 !important;
  pointer-events: none !important;
  background-color: transparent !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position:
    20px top,
    left 130px !important;
  background-size:
    120px 120px,
    100% 100px !important;
  background-image:
    var(--tm-user-img1),
    var(--tm-img2) !important;
}
.tm-para-user::after {
  content: '' !important;
  position: absolute !important;
  top: 264px !important;
  left: 0 !important;
  right: 0 !important;
  height: 140px !important;
  z-index: 5 !important;
  pointer-events: none !important;
  background-image: var(--tm-user-img3) !important;
  background-position: center center !important;
  background-size: 100% auto !important;
  background-repeat: no-repeat !important;
}

/* ════════════════════════════════════════════════════════════
   6. Header 骨架
   ════════════════════════════════════════════════════════════ */
.tc-header,
.tc-header-user {
  position: absolute !important;
  inset: 0 !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  pointer-events: none !important;
  z-index: 20 !important;
  display: block !important;
}

.tc-header-main {
  position: absolute !important;
  inset: 0 !important;
  display: block !important;
  pointer-events: none !important;
  z-index: 20 !important;
}

/* ── (FR.EEDOM) ── */
.tc-header-main::before,
.tm-para-user .tc-header-user::before {
  content: '(FR.EEDOM)' !important;
  position: absolute !important;
  top: 32px !important;
  left: 0 !important;
  right: 0 !important;
  height: 100px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 15px !important;
  letter-spacing: 3px !important;
  font-weight: 700 !important;
  color: #b8b8b0 !important;
  text-transform: uppercase !important;
  opacity: 0.85 !important;
  pointer-events: none !important;
  z-index: 999 !important;
}

/* ── #00 ── */
.tc-header-main::after,
.tm-para-user .tc-header-user::after {
  content: '#00' !important;
  position: absolute !important;
  top: 15px !important;
  left: 115px !important;
  right: auto !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  font-style: normal !important;
  color: #dcdcd2 !important;
  letter-spacing: 1px !important;
  line-height: 1 !important;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9) !important;
  z-index: 999 !important;
  pointer-events: none !important;
}

/* ── 容器 ── */
.tc-meta-area,
.tc-meta-stats {
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 20 !important;
  margin: 0 !important;
  padding: 0 !important;
}

.tc-meta-subtitle,
.tc-meta-extra-1,
.tc-meta-extra-2,
.tc-divider,
.tc-header-deco-top,
.tc-header-deco-bottom,
.tc-avatar-badge { display: none !important; }

/* ════════════════════════════════════════════════════════════
   7. 统计标签
   ════════════════════════════════════════════════════════════ */
.tc-stat {
  position: absolute !important;
  display: inline-block !important;
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-weight: 700 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  box-shadow: none !important;
  text-transform: none !important;
}

/* ── 楼层数 #01 —— 角色 ── */
.tc-stat[data-label="page"] {
  top: 120px !important;
  right: 22px !important;
  left: auto !important;
  color: #dcdcd2 !important;
  font-size: 0 !important;
  letter-spacing: 1px !important;
  font-weight: 700 !important;
  font-style: normal !important;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9) !important;
  z-index: 999 !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}
.tc-stat[data-label="page"]::before {
  content: '#' counter(msg, decimal-leading-zero) !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  font-style: normal !important;
  color: #dcdcd2 !important;
  letter-spacing: 1px !important;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9) !important;
  z-index: 999 !important;
}

/* ── 楼层数 #01 —— 用户 ── */
.tm-para-user .tc-avatar-frame-user::before {
  content: '#' counter(msg, decimal-leading-zero) !important;
  position: absolute !important;
  top: 108px !important;
  right: 5px !important;
  left: auto !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  font-style: normal !important;
  color: #dcdcd2 !important;
  letter-spacing: 1px !important;
  line-height: 1 !important;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9) !important;
  z-index: 999 !important;
  pointer-events: none !important;
}

/* ── 计时 / 字数 —— 角色 ── */
.tc-stat[data-label="words"] {
  top: 95px !important;
  left: 50% !important;
  right: auto !important;
  transform: translateX(-50%) !important;
  color: #888888 !important;
  font-size: 12px !important;
  font-style: italic !important;
  font-weight: 700 !important;
  letter-spacing: 0.5px !important;
  z-index: 999 !important;
}
.tc-stat[data-label="words"]::before {
  content: '52.00s / ' !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-style: italic !important;
  font-weight: 700 !important;
  color: #888888 !important;
}
.tc-stat[data-label="words"]::after {
  content: 't' !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-style: italic !important;
  font-weight: 700 !important;
  color: #888888 !important;
  font-size: 12px !important;
  letter-spacing: 0.5px !important;
}

/* ── 计时 / 字数 —— 用户 ── */
.tm-para-user .tc-avatar-frame-user::after {
  content: '13.14s / 200t' !important;
  position: absolute !important;
  top: 80px !important;
  right: 200px !important;
  left: auto !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 12px !important;
  font-style: italic !important;
  font-weight: 700 !important;
  letter-spacing: 0.5px !important;
  color: #888888 !important;
  white-space: nowrap !important;
  z-index: 999 !important;
  pointer-events: none !important;
}

/* ── 名字 · 日期 · 时间 ── */
.tc-meta-title {
  position: absolute !important;
  top: 408px !important;
  left: 20px !important;
  right: auto !important;
  color: #888888 !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 0.1em !important;
  line-height: 1 !important;
  text-align: left !important;
  text-shadow: none !important;
  z-index: 999 !important;
}
.tc-stat[data-label="date"] {
  top: 408px !important;
  right: 78px !important;
  left: auto !important;
  color: #888888 !important;
  font-size: 11px !important;
  font-style: italic !important;
  font-weight: 700 !important;
  letter-spacing: 0.5px !important;
  z-index: 999 !important;
}
.tc-stat[data-label="time"] {
  top: 408px !important;
  right: 20px !important;
  left: auto !important;
  color: #888888 !important;
  font-size: 11px !important;
  font-style: italic !important;
  font-weight: 700 !important;
  letter-spacing: 0.5px !important;
  z-index: 999 !important;
}

/* ════════════════════════════════════════════════════════════
   ★★★ 头像位置 ★★★
   ════════════════════════════════════════════════════════════ */
.tc-avatar-area {
  position: absolute !important;
  top: 12px !important;
  right: 20px !important;
  left: auto !important;
  bottom: auto !important;
  z-index: 10 !important;
  pointer-events: auto !important;
  width: 120px !important;
  height: 120px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
}
.tc-avatar-frame {
  width: 100% !important;
  height: 100% !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  overflow: hidden !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
}
.tc-avatar-img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: center !important;
  border-radius: 0 !important;
  filter: none !important;
  opacity: 1 !important;
}

.tc-avatar-area-user,
.tc-avatar-frame-user {
  position: absolute !important;
  top: 0px !important;
  right: -3px !important;
  left: auto !important;
  bottom: auto !important;
  z-index: 10 !important;
  width: 120px !important;
  height: 120px !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  overflow: visible !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: block !important;
  pointer-events: auto !important;
}
.tc-avatar-frame-user img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: center !important;
  border-radius: 0 !important;
  overflow: hidden !important;
}

/* ════════════════════════════════════════════════════════════
   9. 正文
   ════════════════════════════════════════════════════════════ */
.tm-body-char,
.tm-body-user {
  color: var(--tm-ink) !important;
  font-weight: 400 !important;
  line-height: 1.85 !important;
  letter-spacing: 0.045em !important;
  text-align: left !important;
  padding-left: 4px !important;
  padding-right: 4px !important;
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 8 !important;
}
.tm-body-user { color: var(--tm-mark) !important; }

.tm-para-block {
  margin: 0 0 0.95em !important;
  text-indent: 2em !important;
  text-align: left !important;
}
.tm-para-block:last-child { margin-bottom: 0 !important; }
.tm-para-block:has(.tm-quote-block),
.tm-quote-block { text-indent: 0 !important; }

/* ════════════════════════════════════════════════════════════
   10. 文字格式
   ════════════════════════════════════════════════════════════ */
.tm-bold {
  color: #ffffff !important;
  background: transparent !important;
  font-weight: 700 !important;
  border-bottom: 1px solid var(--tm-underline) !important;
  padding-bottom: 1px !important;
}
.tm-action {
  color: var(--tm-muted) !important;
  font-style: italic !important;
}
.tm-del {
  color: var(--tm-muted) !important;
  text-decoration-color: var(--tm-line) !important;
}
.tm-quote-block {
  border-left: 3px solid #3a3a3a !important;
  background: rgba(255, 255, 255, 0.03) !important;
  color: var(--tm-ink) !important;
  padding: 8px 14px !important;
  border-radius: 0 !important;
  margin: 0 0 0.8em !important;
  font-style: italic !important;
}
.tm-stream-cursor {
  background: var(--tm-accent) !important;
  width: 2px !important;
  animation: tmBlink 0.8s steps(2) infinite !important;
}
@keyframes tmBlink { 50% { opacity: 0; } }

/* ════════════════════════════════════════════════════════════
   ★★★ 思维链 —— 折叠 + 展开 ★★★
   ════════════════════════════════════════════════════════════ */
.tm-thinking-toggle {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 6px 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  cursor: pointer !important;
}
.tm-thinking-toggle .tm-thinking-icon,
.tm-thinking-toggle .tm-thinking-caret {
  display: none !important;
}
.tm-thinking-toggle .tm-thinking-label {
  font-size: 0 !important;
  color: transparent !important;
  line-height: 1.4 !important;
  display: inline-block !important;
  text-align: center !important;
}
.tm-thinking-toggle .tm-thinking-label::before {
  content: '┈┈・୨ ✦ ୧・┈┈' !important;
  display: inline-block !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 13px !important;
  color: #888888 !important;
  letter-spacing: 2px !important;
  line-height: 1.4 !important;
}
.tm-thinking-toggle:hover .tm-thinking-label::before {
  color: #dcdcd2 !important;
}
.tm-thinking-toggle[aria-expanded="true"] .tm-thinking-label::before,
.tm-thinking-toggle.active .tm-thinking-label::before,
.tm-thinking-toggle.open .tm-thinking-label::before,
.tm-thinking-toggle.is-open .tm-thinking-label::before,
details[open] .tm-thinking-label::before {
  color: #b8b8b0 !important;
}
.tm-thinking-body,
.tm-thinking-content,
.tm-thinking-detail,
.tm-thinking-panel,
.tm-thinking-expanded {
  background: #1a1a1a !important;
  border: 1px solid #2a2a2a !important;
  border-radius: 8px !important;
  padding: 12px 14px !important;
  margin: 6px 0 !important;
  color: #9d9d9d !important;
  font-family: 'Times New Roman', Georgia, serif !important;
  font-size: 13px !important;
  line-height: 1.65 !important;
  letter-spacing: 0.02em !important;
}
.tm-thinking-body *,
.tm-thinking-content *,
.tm-thinking-detail *,
.tm-thinking-panel *,
.tm-thinking-expanded * {
  color: inherit !important;
  font-family: inherit !important;
}

/* ════════════════════════════════════════════════════════════
   11. 输入区 —— 输入栏行高 0.9，收窄
   ════════════════════════════════════════════════════════════ */
.tm-compose {
  background: var(--tm-topbar) !important;
  border-top: 1px solid var(--tm-line) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
.tm-compose-row { gap: 8px !important; }

.tm-input {
  background: var(--tm-paper) !important;
  color: var(--tm-ink) !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  padding: 6px 14px !important;      /* ★ 上下内边距 */
  font-family: inherit !important;
  line-height: 0.9 !important;       /* ★ 输入栏行高 */
  min-height: 28px !important;       /* ★ 输入框最小高度 */
  max-height: 120px !important;
  height: auto !important;
  resize: none !important;
  box-sizing: border-box !important;
  caret-color: var(--tm-accent) !important;
  box-shadow: none !important;
}
.tm-input::placeholder {
  color: var(--tm-muted) !important;
  opacity: 0.75 !important;
}
.tm-input:focus {
  border-color: var(--tm-underline) !important;
  outline: none !important;
  box-shadow: none !important;
}

.tm-send-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  width: 42px !important;
  height: 42px !important;
  box-shadow: none !important;
  transition: none !important;
}
.tm-send-btn.ready,
.tm-send-btn:not(:disabled):hover {
  background: var(--tm-accent) !important;
  border-color: var(--tm-accent) !important;
  color: #141414 !important;
}
.tm-send-btn.ready svg,
.tm-send-btn.ready svg *,
.tm-send-btn:not(:disabled):hover svg,
.tm-send-btn:not(:disabled):hover svg * {
  color: #141414 !important;
  stroke: #141414 !important;
}

.tm-compose-toolbar {
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  gap: 0 !important;
  padding: 0 !important;
}
.tm-regen-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 0 !important;
  border-right: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transition: none !important;
  padding: 8px 10px !important;
}
.tm-regen-btn:last-of-type,
.tm-regen-btn:last-child { border-right: 0 !important; }
.tm-regen-btn:hover {
  background: var(--tm-paper-soft) !important;
  color: #ffffff !important;
}
.tm-regen-btn.active {
  background: var(--tm-accent) !important;
  color: #141414 !important;
  border-color: var(--tm-accent) !important;
}
.tm-regen-btn svg,
.tm-regen-btn svg * {
  color: inherit !important;
  stroke: inherit !important;
}
.tm-regen-btn.active svg,
.tm-regen-btn.active svg * {
  color: #141414 !important;
  stroke: #141414 !important;
}

/* 修复底栏图标看不清 */
.tm-compose-toolbar .tm-regen-btn,
.tm-compose-toolbar .tm-regen-btn svg,
.tm-compose-toolbar .tm-regen-btn svg *,
.tm-compose-toolbar .tm-suggestions-btn,
.tm-compose-toolbar .tm-suggestions-btn svg,
.tm-compose-toolbar .tm-suggestions-btn svg *,
.tm-compose svg.lucide,
.tm-compose svg.lucide * {
  stroke: #dcdcd2 !important;
  color: #dcdcd2 !important;
  fill: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}
.tm-compose-toolbar .tm-regen-btn.active,
.tm-compose-toolbar .tm-regen-btn.active svg,
.tm-compose-toolbar .tm-regen-btn.active svg *,
.tm-compose-toolbar .tm-suggestions-btn.active,
.tm-compose-toolbar .tm-suggestions-btn.active svg,
.tm-compose-toolbar .tm-suggestions-btn.active svg * {
  stroke: #141414 !important;
  color: #141414 !important;
}

.tm-suggestions-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 0 !important;
  border-left: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  padding: 8px 12px !important;
}
.tm-suggestions-btn:hover { background: var(--tm-paper-soft) !important; }
.tm-suggestions-btn.active {
  background: var(--tm-underline) !important;
  color: var(--tm-ink) !important;
}
.tm-suggestions-chevron { color: inherit !important; }

/* ════════════════════════════════════════════════════════════
   12. 建议面板 / 长按菜单 / 抽屉
   ════════════════════════════════════════════════════════════ */
.tm-suggestions-panel {
  background: var(--tm-paper) !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  box-shadow: 0 -12px 32px rgba(0, 0, 0, 0.6) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
}
.tm-suggestion-item {
  background: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid var(--tm-line-soft) !important;
  border-radius: 0 !important;
  padding: 12px 16px !important;
}
.tm-suggestion-item:last-child { border-bottom: 0 !important; }
.tm-suggestion-item:hover { background: var(--tm-paper-soft) !important; }
.tm-suggestion-direction {
  color: var(--tm-muted) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  font-size: 10px !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
}
.tm-suggestion-text,
.tm-suggestion-text-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border-radius: 0 !important;
  line-height: 1.7 !important;
  letter-spacing: 0.045em !important;
  text-align: left !important;
}
.tm-suggestion-text-btn:hover { color: #ffffff !important; }
.tm-suggestion-reroll {
  color: var(--tm-muted) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
}
.tm-suggestion-reroll:hover {
  color: var(--tm-accent) !important;
  border-color: var(--tm-underline) !important;
}
.tm-suggestion-dot {
  background: var(--tm-underline) !important;
  border-radius: 0 !important;
}
.tm-suggestion-error {
  color: #e57373 !important;
  font-size: 11px !important;
}

.tm-context-menu {
  background: var(--tm-paper) !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
}
.tm-context-menu button {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border-radius: 0 !important;
  border-bottom: 1px solid var(--tm-line-soft) !important;
}
.tm-context-menu button:last-child { border-bottom: 0 !important; }
.tm-context-menu button:hover { background: var(--tm-paper-soft) !important; }
.tm-ctx-delete { color: #e57373 !important; }

.tm-edit-textarea {
  background: var(--tm-paper) !important;
  color: var(--tm-ink) !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
  font-family: inherit !important;
  line-height: 1.7 !important;
}
.tm-edit-confirm {
  color: #141414 !important;
  background: var(--tm-accent) !important;
  border-radius: 0 !important;
  border: 0 !important;
}
.tm-edit-cancel {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
}

/* ════════════════════════════════════════════════════════════
   13. 多选底栏 / 历史栏 / 语音 / 翻译 / 分页抽屉
   ════════════════════════════════════════════════════════════ */
.tm-multiselect-bar,
.tm-history-bar {
  background: var(--tm-topbar) !important;
  border-top: 1px solid var(--tm-line) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
.tm-ms-count,
.tm-history-bar { color: var(--tm-muted) !important; }
.tm-ms-cancel,
.tm-history-bar-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
}
.tm-ms-delete {
  color: #141414 !important;
  background: var(--tm-accent) !important;
  border: 0 !important;
  border-radius: 0 !important;
}

.tm-voice-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
}
.tm-voice-btn:hover,
.tm-voice-btn.playing {
  background: var(--tm-accent) !important;
  color: #141414 !important;
  border-color: var(--tm-accent) !important;
}
.tm-voice-icon,
.tm-voice-label { color: inherit !important; }
.tm-voice-spinner { color: var(--tm-accent) !important; }
.tm-voice-wave span {
  background: var(--tm-accent) !important;
  border-radius: 0 !important;
}

.tm-translation-section {
  border-left: 2px solid var(--tm-line) !important;
  padding-left: 14px !important;
  margin-top: 12px !important;
}
.tm-translation-label {
  color: var(--tm-muted) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  font-size: 10px !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
}
.tm-translation-arrow { color: var(--tm-muted) !important; }
.tm-translation-body {
  color: var(--tm-muted) !important;
  line-height: 1.7 !important;
}

.tm-session-browser-overlay {
  background: rgba(0, 0, 0, 0.65) !important;
  backdrop-filter: none !important;
}
.tm-session-browser {
  background: var(--tm-bg) !important;
  border-left: 1px solid var(--tm-line) !important;
  box-shadow: -16px 0 48px rgba(0, 0, 0, 0.6) !important;
  color: var(--tm-ink) !important;
}
.tm-session-browser-header {
  background: var(--tm-topbar) !important;
  border-bottom: 1px solid var(--tm-line) !important;
}
.tm-session-browser-title {
  color: var(--tm-ink) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
}
.tm-session-list { background: transparent !important; }
.tm-session-item {
  background: var(--tm-paper) !important;
  border: 1px solid var(--tm-line-soft) !important;
  border-radius: 0 !important;
  padding: 12px 16px !important;
}
.tm-session-item:hover { background: var(--tm-paper-soft) !important; }
.tm-session-item.active {
  background: var(--tm-underline) !important;
  border-color: var(--tm-underline) !important;
}
.tm-session-item.merge-selected {
  background: var(--tm-paper-soft) !important;
  border-color: var(--tm-accent) !important;
}
.tm-session-item-name {
  color: var(--tm-ink) !important;
  font-weight: 500 !important;
}
.tm-session-item-meta {
  color: var(--tm-muted) !important;
  font-size: 11px !important;
}
.tm-session-new-btn {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 1px solid var(--tm-line) !important;
  border-radius: 0 !important;
}
.tm-session-new-btn:hover {
  background: var(--tm-accent) !important;
  color: #141414 !important;
  border-color: var(--tm-accent) !important;
}

/* ════════════════════════════════════════════════════════════
   14. 加载中
   ════════════════════════════════════════════════════════════ */
.tm-loading-container { background: transparent !important; }
.tm-loading-text {
  color: var(--tm-muted) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  font-size: 11px !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
}

/* ════════════════════════════════════════════════════════════
   15. 全矩形兜底
   ════════════════════════════════════════════════════════════ */
.tm-header *, .tm-header *::before, .tm-header *::after,
.tm-compose *, .tm-compose *::before, .tm-compose *::after,
.tm-para-char *, .tm-para-char *::before, .tm-para-char *::after,
.tm-para-user *, .tm-para-user *::before, .tm-para-user *::after,
.tc-header *, .tc-header *::before, .tc-header *::after,
.tc-header-user *, .tc-header-user *::before, .tc-header-user *::after,
.tm-suggestions-panel *, .tm-context-menu *, .tm-session-browser * {
  border-radius: 0 !important;
}

/* ============================================================
   ★发送按钮（有字状态）—— 保持默认外观，不变化
   ════════════════════════════════════════════════════════════ */
.tm-send-btn.ready,
.tm-send-btn.ready:not(:disabled),
.tm-send-btn.ready:hover,
.tm-compose-row .tm-send-btn.ready,
.tm-compose .tm-send-btn.ready {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border: 1px solid var(--tm-line) !important;
  border-color: var(--tm-line) !important;
  color: var(--tm-ink) !important;
  box-shadow: none !important;
}
.tm-send-btn.ready svg,
.tm-send-btn.ready svg *,
.tm-compose-row .tm-send-btn.ready svg,
.tm-compose-row .tm-send-btn.ready svg * {
  color: var(--tm-ink) !important;
  stroke: var(--tm-ink) !important;
  fill: none !important;
}

/*⁣​⁠⁠⁠⁠​​‍​‌​​‌‍​⁠‌‍​‍‌⁠‌​⁠‌‍‍⁠​‌‌‌⁠‍‌‌​​‌‍​‌​⁠‌​⁠​‌‍​⁠‌‌⁠‌⁠‌⁠‌‍‌‌⁣ ============================================================
   此时此刻 × 自由副刊·日间 · 完整版
   ============================================================
   ▸ 三行头图用伪元素 cover，绝不变形
   ▸ 用户 (FR.EEDOM) / 楼层数 / 计时 全部对齐
   ▸ 思维链折叠装饰文案 + 展开卡片
   ▸ 底栏图标 / 输入框 / 头像 可调
   ▸ 输入栏行高 0.9，收窄
   ============================================================ */

:root {
  --tm-ink:       #2a2a2a;
  --tm-mark:      #555555;
  --tm-muted:     #888888;
  --tm-line:      #e0e0e0;
  --tm-line-soft: #f0f0f0;
  --tm-bg:        #f5f5f5;
  --tm-topbar:    rgba(250, 250, 250, 0.9);
  --tm-paper:     rgba(255, 255, 255, 0.92);
  --tm-paper-soft:rgba(247, 247, 247, 0.9);
  --tm-accent:    #333333;
  --tm-underline: #cccccc;

  /* ★ 三行图床：角色 */
  --tm-char-img1: url('https://imgbed.heliar.top/i/QJ6qo1JFbEw7nEXJ_1789071311664.webp');
  --tm-char-img3: url('https://imgbed.heliar.top/i/CxNnpvsr8zbdfMZw_1789502077118.webp');
  /* ★ 三行图床：用户 */
  --tm-user-img1: url('https://imgbed.heliar.top/i/inwMoRHrSJHd3P9x_1789071316031.webp');
  --tm-user-img3: url('https://imgbed.heliar.top/i/kslCpffioMmabDGY_1789502062697.webp');
  /* ★ 中横图：两边共用 */
  --tm-img2:      url('https://imgbed.heliar.top/i/jE-P4YR3JE3zqDw5_1789407725271_CocoAI_20260915_014226_1.webp');
}

/* ════════════════════════════════════════════════════════════
   1. 全局底色
   ════════════════════════════════════════════════════════════ */
#this-moment-screen {
  background: var(--tm-bg) !important;
  color: var(--tm-ink) !important;
}
.tm-bg-image { display: none !important; }
.tm-bg-overlay {
  background: rgba(245, 245, 245, 0.55) !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
::selection {
  background: var(--tm-underline) !important;
  color: var(--tm-ink) !important;
}

/* ════════════════════════════════════════════════════════════
   2. 顶栏
   ════════════════════════════════════════════════════════════ */
.tm-header {
  background: var(--tm-topbar) !important;
  border-bottom: 1px solid var(--tm-line) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
.tm-header-name {
  color: var(--tm-ink) !important;
  font-family: Georgia, 'Times New Roman', serif !important;
  letter-spacing: 0.04em !important;
}
.tm-top-vs { color: var(--tm-muted) !important; }

.tm-btn-icon {
  color: var(--tm-ink) !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
}
