/* ==================================================
   自适应双模式版（新日间图 · iMessage发送键 · 极简透字）☁️🖤
   ================================================== */

/* —— CSS变量定义 —— */
:root {
  --bg-base: #ecedec;
  --bg-card: transparent;
  --text-main: #2f2f2f;
  --text-mute: #7a7a7a;
  --accent: #4a4a4a;
  --header-bg: rgba(236, 237, 236, 0.15);
  --compose-bg: rgba(236, 237, 236, 0.15);
  --input-bg: rgba(255,255,255,0.5);
  /* ✅✅✅ 日间背景换成你要的新图 ✅✅✅ */
  --overlay-bg: url("https://iili.io/CjSvF99.md.jpg") center/cover no-repeat fixed;
  --btn-icon-color: var(--accent);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-base: #0f0f0f;
    --bg-card: transparent;
    --text-main: #e8e8e8;
    --text-mute: #999999;
    --accent: #aaaaaa;
    --header-bg: rgba(15, 15, 15, 0.15);
    --compose-bg: rgba(15, 15, 15, 0.15);
    --input-bg: rgba(40,40,40,0.6);
    --overlay-bg:
      linear-gradient(rgba(0, 0, 0, 0.45), rgba(0, 0, 0, 0.45)),
      url("https://iili.io/CjkYo37.md.jpg") center/cover no-repeat fixed;
  }
}

/* —— 根容器 —— */
#this-moment-screen {
  background: var(--bg-base) !important;
  color: var(--text-main) !important;
  font-family: Georgia, "Noto Serif SC", serif !important;
}

.tm-bg-image { opacity: 0 !important; }

.tm-bg-overlay {
  background: var(--overlay-bg) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ==================================================
   ✅ 顶栏（上移+轻磨砂透字）
   ================================================== */
.tm-header {
  background: var(--header-bg) !important;
  backdrop-filter: blur(8px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(150%) !important;
  border-bottom: none !important;
  box-shadow: none !important;
  padding: calc(env(safe-area-inset-top) - 6px) 8px 10px !important;
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

.tm-header::before { display: none !important; }

.tm-top-vs,
.tm-header-name,
.tm-top-vs::before,
.tm-top-vs::after {
  display: none !important;
  content: none !important;
}

/* ==================================================
   ✅ 左右按钮：隐形可点
   ================================================== */
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  background: transparent !important;
  border: none !important;
  color: transparent !important;
  padding: 14px 26px !important;
  margin-top: 0 !important;
  min-width: 44px !important;
  min-height: 44px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  pointer-events: auto !important;
}

.tm-btn-icon {
  color: var(--btn-icon-color) !important;
  visibility: visible !important;
  pointer-events: auto !important;
  font-size: 18px !important;
}

/* ==================================================
   ✅ 故事区卡片（全透明）
   ================================================== */
.tm-story {
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 0 !important;
  background: transparent !important;
}

.tm-para {
  width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}

.tm-para-char,
.tm-para-user {
  background: var(--bg-card) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  position: relative !important;
  overflow: hidden !important;
}

/* ==================================================
   Header 骨架
   ================================================== */
.tc-header {
  padding: 18px 18px 10px !important;
  border-bottom: none !important;
  position: relative !important;
}

.tc-header::after { display: none !important; }

.tc-meta-subtitle::before {
  content: "明明說了再見其實也等於永別" !important;
  display: block !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  color: var(--accent) !important;
  letter-spacing: 0.15em !important;
  text-transform: none !important;
  margin-bottom: 6px !important;
}

.tc-meta-title {
  font-size: 20px !important;
  font-weight: 700 !important;
  color: var(--text-main) !important;
}

.tc-stat {
  background: transparent !important;
  color: var(--text-mute) !important;
  border: none !important;
  font-size: 9px !important;
  letter-spacing: 0.1em !important;
  text-transform: uppercase !important;
}

/* ==================================================
   ✅ 正文文字
   ================================================== */
.tm-body-char {
  color: var(--text-main) !important;
  font-size: 16px !important;
  line-height: 1.8 !important;
  text-align: justify !important;
  text-indent: 2em !important;
  padding: 18px 20px !important;
  text-shadow: none !important;
}

.tm-body-user {
  color: var(--text-mute) !important;
  font-style: italic !important;
  font-size: 16px !important;
  line-height: 1.8 !important;
  text-align: justify !important;
  text-indent: 2em !important;
  padding: 18px 20px !important;
  text-shadow: none !important;
}

.tm-bold {
  color: var(--text-main) !important;
  font-weight: 700 !important;
  background: transparent !important;
  padding: 0 !important;
}

.tm-quote-block {
  background: transparent !important;
  border-left: none !important;
  padding: 0.85em 1em !important;
  margin: 1em 0 !important;
  line-height: 1.8 !important;
  font-size: 16px !important;
  color: var(--text-mute) !important;
  font-style: italic !important;
  text-indent: 0 !important;
}

/* ==================================================
   ✅ 卡片底部文案
   ================================================== */
.tm-para-char::after {
  content: "緣分淺淺  如雨漸漸" !important;
  display: block !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 0.15em !important;
  text-transform: none !important;
  color: var(--text-mute) !important;
  text-align: center !important;
  padding: 14px 16px !important;
  border-top: none !important;
  background: transparent !important;
  margin-top: 0 !important;
}

/* ==================================================
   ✅ 输入区（横向排列+居中对齐）
   ================================================== */
.tm-compose {
  background: var(--compose-bg) !important;
  backdrop-filter: blur(8px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(150%) !important;
  border-top: none !important;
  box-shadow: none !important;
  padding: 8px 12px 12px !important;
}

.tm-compose-toolbar {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 8px !important;
  width: 100% !important;
}

.tm-regen-btn {
  color: var(--text-mute) !important;
  border: none !important;
  background: transparent !important;
  border-radius: 0 !important;
  font-size: 11px !important;
  letter-spacing: 0.05em !important;
  text-transform: uppercase !important;
  padding: 8px 4px !important;
  flex-shrink: 0 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(1) {
  color: var(--accent) !important;
}

.tm-input {
  background: var(--input-bg) !important;
  border: none !important;
  color: var(--text-main) !important;
  font-family: Georgia, serif !important;
  font-size: 13px !important;
  padding: 10px 14px !important;
  border-radius: 18px !important;
  flex-grow: 1 !important;
  min-height: 36px !important;
  align-self: center !important;
}

.tm-input::placeholder {
  color: var(--text-mute) !important;
  font-style: italic !important;
}

/* ==================================================
   ✅ 发送键：iMessage风格（圆角矩形+右上箭头）
   ================================================== */
.tm-send-btn {
  background: var(--accent) !important;
  color: transparent !important;
  border-radius: 18px !important;
  width: auto !important;
  height: 36px !important;
  min-width: 36px !important;
  min-height: 36px !important;
  padding: 0 10px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-weight: normal !important;
  text-transform: none !important;
  flex-shrink: 0 !important;
  position: relative !important;
}

.tm-send-btn svg,
.tm-send-btn i,
.tm-send-btn .tm-btn-icon {
  display: none !important;
}

.tm-send-btn::after {
  content: "" !important;
  display: block !important;
  width: 6px !important;
  height: 6px !important;
  border-top: 2px solid var(--bg-base) !important;
  border-right: 2px solid var(--bg-base) !important;
  transform: rotate(-45deg) translate(-1px, 1px) !important;
}

/* ==================================================
   建议面板
   ================================================== */
.tm-suggestions-panel {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  border-radius: 0 !important;
}

.tm-suggestion-item {
  border-bottom: none !important;
  padding: 10px 16px !important;
}

.tm-suggestion-direction {
  color: var(--accent) !important;
  font-size: 9px !important;
  letter-spacing: 0.1em !important;
  text-transform: uppercase !important;
}

.tm-suggestion-text {
  color: var(--text-main) !important;
  font-size: 15px !important;
  line-height: 1.8 !important;
}

/* ==================================================
   滚动条
   ================================================== */
.tm-story::-webkit-scrollbar { width: 4px !important; }
.tm-story::-webkit-scrollbar-thumb { background: var(--accent) !important; opacity: 0.5; }
.tm-story::-webkit-scrollbar-track { background: transparent !important; }
